CREATE TABLE specialty_order_links(id TEXT PRIMARY KEY,order_id TEXT NOT NULL UNIQUE REFERENCES retail_orders(id),order_version INTEGER NOT NULL,case_id TEXT NOT NULL REFERENCES specialty_cases(id),store_id TEXT NOT NULL REFERENCES stores(id),customer_id TEXT NOT NULL REFERENCES customers(id),created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),FOREIGN KEY(order_id,order_version,customer_id,store_id) REFERENCES retail_order_versions(order_id,version,customer_id,store_id));

CREATE TABLE specialty_order_approvals(id TEXT PRIMARY KEY,link_id TEXT NOT NULL REFERENCES specialty_order_links(id),store_id TEXT NOT NULL REFERENCES stores(id),customer_id TEXT NOT NULL REFERENCES customers(id),revision INTEGER NOT NULL CHECK(revision>=1),sequence INTEGER NOT NULL CHECK(sequence>=1),specialty_sequence INTEGER NOT NULL CHECK(specialty_sequence>=1),case_version INTEGER NOT NULL,case_revision INTEGER NOT NULL,consent_id TEXT NOT NULL REFERENCES specialty_consents(id),consent_revision INTEGER NOT NULL,parameter_version_id TEXT NOT NULL REFERENCES parameter_versions(id),parameter_sequence INTEGER NOT NULL CHECK(parameter_sequence>=1),note TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(link_id,revision),UNIQUE(store_id,sequence));

CREATE TABLE specialty_product_lots(id TEXT PRIMARY KEY,link_id TEXT NOT NULL REFERENCES specialty_order_links(id),receive_event_id TEXT NOT NULL REFERENCES processing_events(id),job_id TEXT NOT NULL REFERENCES processing_jobs(id),position INTEGER NOT NULL CHECK(position>=1),quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 999),store_id TEXT NOT NULL REFERENCES stores(id),customer_id TEXT NOT NULL REFERENCES customers(id),created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id));

CREATE TABLE specialty_lot_versions(id TEXT PRIMARY KEY,lot_id TEXT NOT NULL REFERENCES specialty_product_lots(id),store_id TEXT NOT NULL REFERENCES stores(id),customer_id TEXT NOT NULL REFERENCES customers(id),revision INTEGER NOT NULL CHECK(revision>=1),sequence INTEGER NOT NULL CHECK(sequence>=1),trace_status TEXT NOT NULL CHECK(trace_status IN('recorded','unknown')),lot_number TEXT,serial_note TEXT NOT NULL,manufacturer_note TEXT NOT NULL,supplier_note TEXT NOT NULL,source_note TEXT NOT NULL,document_ids_json TEXT NOT NULL CHECK(json_valid(document_ids_json)),attachment_ids_json TEXT NOT NULL CHECK(json_valid(attachment_ids_json)),note TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(lot_id,revision),UNIQUE(store_id,sequence),CHECK((trace_status='recorded' AND length(trim(lot_number)) BETWEEN 1 AND 120) OR(trace_status='unknown' AND lot_number IS NULL)));

CREATE TABLE specialty_execution_refs(event_id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('processing_job','processing','fulfillment','payment','reservation','outbound')),link_id TEXT NOT NULL REFERENCES specialty_order_links(id),approval_id TEXT NOT NULL REFERENCES specialty_order_approvals(id),trace_sequence INTEGER NOT NULL,specialty_sequence INTEGER NOT NULL,parameter_sequence INTEGER NOT NULL,processing_revision INTEGER NOT NULL CHECK(processing_revision>=0),lot_basis_json TEXT NOT NULL CHECK(json_valid(lot_basis_json)),created_at TEXT NOT NULL);

CREATE VIEW specialty_trace_journal AS SELECT store_id,sequence,created_at,'approval' kind,id,link_id root_id FROM specialty_order_approvals UNION ALL SELECT store_id,sequence,created_at,'lot',id,lot_id FROM specialty_lot_versions;

CREATE VIEW specialty_approval_current AS SELECT a.* FROM specialty_order_approvals a WHERE revision=(SELECT max(revision) FROM specialty_order_approvals WHERE link_id=a.link_id);

CREATE VIEW specialty_lot_current AS SELECT v.* FROM specialty_lot_versions v WHERE revision=(SELECT max(revision) FROM specialty_lot_versions WHERE lot_id=v.lot_id);

CREATE VIEW specialty_trace_context AS SELECT l.*,a.id approval_id,a.revision approval_revision,a.case_version,a.case_revision,a.consent_id,a.consent_revision,a.parameter_version_id,a.parameter_sequence,
 coalesce((SELECT max(sequence) FROM specialty_trace_journal WHERE store_id=l.store_id),0) trace_sequence,
 coalesce((SELECT max(sequence) FROM specialty_journal WHERE store_id=l.store_id),0) specialty_sequence,
 CASE WHEN a.id IS NOT NULL AND o.version=l.order_version AND o.status='draft' AND c.version=a.case_version AND c.revision=a.case_revision AND c.status='active' AND c.consent_id=a.consent_id AND c.consent_revision=a.consent_revision AND co.status='active' AND co.revision=a.consent_revision AND p.status='adopted' AND p.version=r.protocol_version AND p.revision=r.protocol_revision AND v.suitability='suitable' AND pv.id=a.parameter_version_id AND pv.status='checked' AND pv.sequence=a.parameter_sequence AND NOT EXISTS(SELECT 1 FROM parameter_attachments x JOIN attachments t ON t.id=x.attachment_id WHERE x.version_id=pv.id AND t.revoked_at IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM json_each(v.attachment_ids_json) x JOIN attachments t ON t.id=x.value WHERE t.revoked_at IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM json_each(cr.attachment_ids_json) x JOIN attachments t ON t.id=x.value WHERE t.revoked_at IS NOT NULL) AND u.active=1 AND u.role='professional' AND u.store_id=l.store_id AND coalesce(us.must_change_password,0)=0 THEN 1 ELSE 0 END can_execute
 FROM specialty_order_links l LEFT JOIN specialty_approval_current a ON a.link_id=l.id JOIN retail_order_versions o ON o.order_id=l.order_id AND o.version=(SELECT max(version) FROM retail_order_versions WHERE order_id=l.order_id) JOIN specialty_cases r ON r.id=l.case_id JOIN specialty_case_current c ON c.case_id=l.case_id LEFT JOIN specialty_case_versions v ON v.case_id=l.case_id AND v.version=a.case_version LEFT JOIN specialty_consent_current co ON co.consent_id=a.consent_id LEFT JOIN specialty_consents cr ON cr.id=a.consent_id JOIN specialty_protocol_current p ON p.protocol_id=r.protocol_id LEFT JOIN parameter_current pv ON pv.order_id=l.order_id AND pv.order_version=l.order_version JOIN users u ON u.id=c.owner_id LEFT JOIN user_security us ON us.user_id=u.id;

CREATE VIEW specialty_lot_basis AS SELECT j.id job_id,COALESCE((SELECT json_group_array(json_object('lot_id',l.id,'version_id',v.id,'revision',v.revision,'quantity',l.quantity,'position',l.position)) FROM (SELECT l.*,v.id version_id,v.revision FROM specialty_product_lots l JOIN specialty_lot_current v ON v.lot_id=l.id WHERE l.job_id=j.id ORDER BY l.id) l JOIN specialty_lot_current v ON v.lot_id=l.id),'[]') basis_json FROM processing_jobs j;

CREATE VIEW specialty_lot_coverage AS SELECT j.id job_id,i.position,
 coalesce((SELECT sum(l.quantity) FROM specialty_product_lots l JOIN specialty_lot_current v ON v.lot_id=l.id WHERE l.job_id=j.id AND l.position=i.position AND v.trace_status='recorded' AND NOT EXISTS(SELECT 1 FROM json_each(v.attachment_ids_json) x JOIN attachments a ON a.id=x.value WHERE a.revoked_at IS NOT NULL)),0) traced_quantity,
 coalesce((SELECT json_extract(x.value,'$.received') FROM processing_events e,json_each(e.snapshot_json) x WHERE e.job_id=j.id AND e.revision=(SELECT max(revision) FROM processing_events WHERE job_id=j.id) AND json_extract(x.value,'$.position')=i.position),0) received_quantity
 FROM processing_jobs j JOIN specialty_order_links s ON s.order_id=j.order_id JOIN retail_order_items i ON i.order_id=j.order_id AND i.version=j.order_version JOIN retail_product_versions p ON p.product_id=i.product_id AND p.version=i.product_version WHERE p.category='lens' ;

CREATE TRIGGER specialty_order_links_no_update BEFORE UPDATE ON specialty_order_links BEGIN SELECT RAISE(ABORT,'specialty trace immutable'); END;

CREATE TRIGGER specialty_order_links_no_delete BEFORE DELETE ON specialty_order_links BEGIN SELECT RAISE(ABORT,'specialty trace immutable'); END;

CREATE TRIGGER specialty_order_links_actor BEFORE INSERT ON specialty_order_links WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND coalesce(s.must_change_password,0)=0 AND u.role IN('manager','reception','professional')) BEGIN SELECT RAISE(ABORT,'specialty trace actor/time'); END;

CREATE TRIGGER specialty_order_approvals_no_update BEFORE UPDATE ON specialty_order_approvals BEGIN SELECT RAISE(ABORT,'specialty trace immutable'); END;

CREATE TRIGGER specialty_order_approvals_no_delete BEFORE DELETE ON specialty_order_approvals BEGIN SELECT RAISE(ABORT,'specialty trace immutable'); END;

CREATE TRIGGER specialty_order_approvals_actor BEFORE INSERT ON specialty_order_approvals WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND coalesce(s.must_change_password,0)=0 AND u.role IN('manager','reception','professional')) BEGIN SELECT RAISE(ABORT,'specialty trace actor/time'); END;

CREATE TRIGGER specialty_product_lots_no_update BEFORE UPDATE ON specialty_product_lots BEGIN SELECT RAISE(ABORT,'specialty trace immutable'); END;

CREATE TRIGGER specialty_product_lots_no_delete BEFORE DELETE ON specialty_product_lots BEGIN SELECT RAISE(ABORT,'specialty trace immutable'); END;

CREATE TRIGGER specialty_product_lots_actor BEFORE INSERT ON specialty_product_lots WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND coalesce(s.must_change_password,0)=0 AND u.role IN('manager','reception','professional')) BEGIN SELECT RAISE(ABORT,'specialty trace actor/time'); END;

CREATE TRIGGER specialty_lot_versions_no_update BEFORE UPDATE ON specialty_lot_versions BEGIN SELECT RAISE(ABORT,'specialty trace immutable'); END;

CREATE TRIGGER specialty_lot_versions_no_delete BEFORE DELETE ON specialty_lot_versions BEGIN SELECT RAISE(ABORT,'specialty trace immutable'); END;

CREATE TRIGGER specialty_lot_versions_actor BEFORE INSERT ON specialty_lot_versions WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND coalesce(s.must_change_password,0)=0 AND u.role IN('manager','reception','professional')) BEGIN SELECT RAISE(ABORT,'specialty trace actor/time'); END;

CREATE TRIGGER specialty_execution_refs_no_update BEFORE UPDATE ON specialty_execution_refs BEGIN SELECT RAISE(ABORT,'specialty trace immutable'); END;

CREATE TRIGGER specialty_execution_refs_no_delete BEFORE DELETE ON specialty_execution_refs BEGIN SELECT RAISE(ABORT,'specialty trace immutable'); END;

CREATE TRIGGER specialty_order_approvals_clock BEFORE INSERT ON specialty_order_approvals WHEN NEW.revision<>coalesce((SELECT max(revision)+1 FROM specialty_order_approvals WHERE link_id=NEW.link_id),1) OR NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM specialty_trace_journal WHERE store_id=NEW.store_id),1) OR EXISTS(SELECT 1 FROM specialty_trace_journal WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR length(trim(NEW.note)) NOT BETWEEN 1 AND 2000 OR length(NEW.note)>2000 OR length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300 BEGIN SELECT RAISE(ABORT,'specialty trace history'); END;

CREATE TRIGGER specialty_lot_versions_clock BEFORE INSERT ON specialty_lot_versions WHEN NEW.revision<>coalesce((SELECT max(revision)+1 FROM specialty_lot_versions WHERE lot_id=NEW.lot_id),1) OR NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM specialty_trace_journal WHERE store_id=NEW.store_id),1) OR EXISTS(SELECT 1 FROM specialty_trace_journal WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR length(trim(NEW.note)) NOT BETWEEN 1 AND 2000 OR length(NEW.note)>2000 OR length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300 BEGIN SELECT RAISE(ABORT,'specialty trace history'); END;

CREATE TRIGGER specialty_link_ready BEFORE INSERT ON specialty_order_links BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM retail_orders o JOIN retail_order_versions v ON v.order_id=o.id JOIN specialty_cases c ON c.id=NEW.case_id JOIN users u ON u.id=NEW.created_by WHERE o.id=NEW.order_id AND v.version=NEW.order_version AND v.version=(SELECT max(version) FROM retail_order_versions WHERE order_id=o.id) AND v.status='draft' AND o.customer_id=NEW.customer_id AND o.store_id=NEW.store_id AND c.customer_id=o.customer_id AND c.store_id=o.store_id AND o.cycle_id=c.cycle_id AND o.cycle_version=c.cycle_version AND u.role='professional' AND NEW.created_at>=v.created_at AND NEW.created_at>=c.created_at) OR EXISTS(SELECT 1 FROM processing_jobs WHERE order_id=NEW.order_id) OR EXISTS(SELECT 1 FROM payment_events WHERE order_id=NEW.order_id) OR EXISTS(SELECT 1 FROM inventory_order_events WHERE order_id=NEW.order_id) OR EXISTS(SELECT 1 FROM retail_order_items i JOIN retail_product_versions p ON p.product_id=i.product_id AND p.version=i.product_version WHERE i.order_id=NEW.order_id AND i.version=NEW.order_version AND p.category NOT IN('lens','service')) OR NOT EXISTS(SELECT 1 FROM retail_order_items i JOIN retail_product_versions p ON p.product_id=i.product_id AND p.version=i.product_version WHERE i.order_id=NEW.order_id AND i.version=NEW.order_version AND p.category='lens') THEN RAISE(ABORT,'specialty original order mismatch or already executed') END; END;

CREATE TRIGGER specialty_approval_ready BEFORE INSERT ON specialty_order_approvals BEGIN
 SELECT CASE WHEN NEW.specialty_sequence<>(SELECT coalesce(max(sequence),0) FROM specialty_journal WHERE store_id=NEW.store_id) OR NOT EXISTS(SELECT 1 FROM specialty_order_links l JOIN specialty_case_current c ON c.case_id=l.case_id JOIN users au ON au.id=NEW.created_by AND au.role='professional' JOIN specialty_cases r ON r.id=c.case_id JOIN specialty_case_versions v ON v.case_id=c.case_id AND v.version=c.version JOIN specialty_protocol_current p ON p.protocol_id=r.protocol_id JOIN specialty_protocol_versions rule ON rule.protocol_id=r.protocol_id AND rule.version=r.protocol_version JOIN specialty_consent_current co ON co.consent_id=c.consent_id JOIN specialty_consents cr ON cr.id=co.consent_id JOIN parameter_current pv ON pv.order_id=l.order_id AND pv.order_version=l.order_version JOIN retail_order_versions o ON o.order_id=l.order_id AND o.version=l.order_version WHERE l.id=NEW.link_id AND l.customer_id=NEW.customer_id AND l.store_id=NEW.store_id AND c.version=NEW.case_version AND c.revision=NEW.case_revision AND c.status='active' AND c.owner_id=NEW.created_by AND v.suitability='suitable' AND p.version=r.protocol_version AND p.revision=r.protocol_revision AND p.status='adopted' AND co.status='active' AND co.consent_id=NEW.consent_id AND co.revision=NEW.consent_revision AND cr.case_id=l.case_id AND cr.case_version=c.version AND pv.id=NEW.parameter_version_id AND pv.sequence=NEW.parameter_sequence AND pv.status='checked' AND o.status='draft' AND o.version=(SELECT max(version) FROM retail_order_versions WHERE order_id=l.order_id) AND NEW.created_at>=l.created_at AND NEW.created_at>=c.created_at AND NEW.created_at>=co.created_at AND NEW.created_at>=pv.event_created_at AND (rule.require_assessment_evidence=0 OR json_array_length(v.document_ids_json)+json_array_length(v.attachment_ids_json)>0) AND (rule.require_consent_evidence=0 OR json_array_length(cr.document_ids_json)+json_array_length(cr.attachment_ids_json)>0) AND NOT EXISTS(SELECT 1 FROM json_each(v.attachment_ids_json) x JOIN attachments a ON a.id=x.value WHERE a.revoked_at IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM json_each(cr.attachment_ids_json) x JOIN attachments a ON a.id=x.value WHERE a.revoked_at IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM parameter_attachments x JOIN attachments a ON a.id=x.attachment_id WHERE x.version_id=pv.id AND a.revoked_at IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM retail_order_items i JOIN retail_product_versions ip ON ip.product_id=i.product_id AND ip.version=i.product_version WHERE i.order_id=l.order_id AND i.version=l.order_version AND ip.category='lens' AND NOT EXISTS(SELECT 1 FROM json_each(pv.manifest_json,'$.values') x WHERE json_extract(x.value,'$.position')=i.position))) THEN RAISE(ABORT,'specialty approval source/owner mismatch') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM specialty_order_links l JOIN processing_jobs j ON j.order_id=l.order_id JOIN processing_events e ON e.job_id=j.id JOIN specialty_order_approvals old ON old.link_id=l.id AND old.revision=1 WHERE l.id=NEW.link_id AND e.action='start' AND old.case_version<>NEW.case_version) THEN RAISE(ABORT,'specialty assessment changed after start') END;
 SELECT CASE WHEN NEW.revision=1 AND NOT EXISTS(SELECT 1 FROM specialty_order_links l WHERE l.id=NEW.link_id AND l.created_at=NEW.created_at AND l.created_by=NEW.created_by) THEN RAISE(ABORT,'specialty initial approval mismatch') END; END;

CREATE TRIGGER specialty_lot_ready BEFORE INSERT ON specialty_product_lots BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM specialty_order_links l JOIN processing_jobs j ON j.order_id=l.order_id AND j.order_version=l.order_version JOIN processing_events e ON e.job_id=j.id WHERE l.id=NEW.link_id AND e.id=NEW.receive_event_id AND e.action='receive' AND e.position=NEW.position AND j.id=NEW.job_id AND l.customer_id=NEW.customer_id AND l.store_id=NEW.store_id AND NEW.created_at>=e.created_at) OR NEW.quantity+coalesce((SELECT sum(quantity) FROM specialty_product_lots WHERE receive_event_id=NEW.receive_event_id),0)>(SELECT quantity FROM processing_events WHERE id=NEW.receive_event_id) THEN RAISE(ABORT,'specialty received lot capacity/source') END; END;

CREATE TRIGGER specialty_lot_version_ready BEFORE INSERT ON specialty_lot_versions BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM specialty_product_lots l WHERE l.id=NEW.lot_id AND l.store_id=NEW.store_id AND l.customer_id=NEW.customer_id AND NEW.created_at>=l.created_at AND (NEW.revision<>1 OR l.created_by=NEW.created_by AND l.created_at=NEW.created_at)) OR length(trim(NEW.serial_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.serial_note)>2000 OR length(trim(NEW.manufacturer_note)) NOT BETWEEN 1 AND 1000 OR length(NEW.manufacturer_note)>1000 OR length(trim(NEW.supplier_note)) NOT BETWEEN 1 AND 1000 OR length(NEW.supplier_note)>1000 OR length(trim(NEW.source_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.source_note)>2000 OR length(NEW.lot_number)>120 OR json_type(NEW.document_ids_json) IS NOT 'array' OR json_array_length(NEW.document_ids_json)>30 OR EXISTS(SELECT 1 FROM json_each(NEW.document_ids_json) x WHERE x.type<>'text' OR length(x.value) NOT BETWEEN 1 AND 100 OR NOT EXISTS(SELECT 1 FROM document_versions d WHERE d.id=x.value AND d.customer_id=NEW.customer_id AND d.created_at<=NEW.created_at )) OR EXISTS(SELECT 1 FROM json_each(NEW.document_ids_json) GROUP BY value HAVING count(*)>1) OR json_type(NEW.attachment_ids_json) IS NOT 'array' OR json_array_length(NEW.attachment_ids_json)>30 OR EXISTS(SELECT 1 FROM json_each(NEW.attachment_ids_json) x WHERE x.type<>'text' OR length(x.value) NOT BETWEEN 1 AND 100 OR NOT EXISTS(SELECT 1 FROM attachments d WHERE d.id=x.value AND d.customer_id=NEW.customer_id AND d.created_at<=NEW.created_at AND d.revoked_at IS NULL)) OR EXISTS(SELECT 1 FROM json_each(NEW.attachment_ids_json) GROUP BY value HAVING count(*)>1) THEN RAISE(ABORT,'specialty lot version/source mismatch') END; END;

CREATE TRIGGER specialty_order_version_lock BEFORE INSERT ON retail_order_versions WHEN NEW.status='draft' AND EXISTS(SELECT 1 FROM specialty_order_links WHERE order_id=NEW.order_id) BEGIN SELECT RAISE(ABORT,'specialty fixed original order'); END;

CREATE TRIGGER processing_jobs_specialty_gate BEFORE INSERT ON processing_jobs WHEN 1 AND EXISTS(SELECT 1 FROM specialty_order_links WHERE order_id=NEW.order_id) BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM specialty_trace_context WHERE order_id=NEW.order_id AND can_execute=1) THEN RAISE(ABORT,'specialty current approval required') END; END;

CREATE TRIGGER processing_jobs_specialty_capture AFTER INSERT ON processing_jobs WHEN 1 BEGIN INSERT INTO specialty_execution_refs SELECT NEW.id,'processing_job',c.id,c.approval_id,c.trace_sequence,c.specialty_sequence,c.parameter_sequence,coalesce((SELECT max(revision) FROM processing_events WHERE job_id=NULL),0),coalesce((SELECT basis_json FROM specialty_lot_basis WHERE job_id=NULL),'[]'),NEW.created_at FROM specialty_trace_context c WHERE c.order_id=NEW.order_id; END;

CREATE TRIGGER processing_events_specialty_gate BEFORE INSERT ON processing_events WHEN NEW.action IN('plan','start','complete') AND EXISTS(SELECT 1 FROM specialty_order_links WHERE order_id=(SELECT order_id FROM processing_jobs WHERE id=NEW.job_id)) BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM specialty_trace_context WHERE order_id=(SELECT order_id FROM processing_jobs WHERE id=NEW.job_id) AND can_execute=1) THEN RAISE(ABORT,'specialty current approval required') END; END;

CREATE TRIGGER processing_events_specialty_capture AFTER INSERT ON processing_events WHEN NEW.action IN('plan','start','complete') BEGIN INSERT INTO specialty_execution_refs SELECT NEW.id,'processing',c.id,c.approval_id,c.trace_sequence,c.specialty_sequence,c.parameter_sequence,coalesce((SELECT max(revision) FROM processing_events WHERE job_id=NEW.job_id),0),coalesce((SELECT basis_json FROM specialty_lot_basis WHERE job_id=NEW.job_id),'[]'),NEW.created_at FROM specialty_trace_context c WHERE c.order_id=(SELECT order_id FROM processing_jobs WHERE id=NEW.job_id); END;

CREATE TRIGGER fulfillment_events_specialty_gate BEFORE INSERT ON fulfillment_events WHEN NEW.action<>'check_fail' AND EXISTS(SELECT 1 FROM specialty_order_links WHERE order_id=(SELECT order_id FROM processing_jobs WHERE id=NEW.job_id)) BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM specialty_trace_context WHERE order_id=(SELECT order_id FROM processing_jobs WHERE id=NEW.job_id) AND can_execute=1) THEN RAISE(ABORT,'specialty current approval required') END; SELECT CASE WHEN NEW.action IN('check_pass','deliver') AND EXISTS(SELECT 1 FROM specialty_lot_coverage WHERE job_id=NEW.job_id AND position=NEW.position AND traced_quantity<received_quantity) THEN RAISE(ABORT,'specialty lot trace incomplete') END; END;

CREATE TRIGGER fulfillment_events_specialty_capture AFTER INSERT ON fulfillment_events WHEN NEW.action<>'check_fail' BEGIN INSERT INTO specialty_execution_refs SELECT NEW.id,'fulfillment',c.id,c.approval_id,c.trace_sequence,c.specialty_sequence,c.parameter_sequence,coalesce((SELECT max(revision) FROM processing_events WHERE job_id=NEW.job_id),0),coalesce((SELECT basis_json FROM specialty_lot_basis WHERE job_id=NEW.job_id),'[]'),NEW.created_at FROM specialty_trace_context c WHERE c.order_id=(SELECT order_id FROM processing_jobs WHERE id=NEW.job_id); END;

CREATE TRIGGER payment_events_specialty_gate BEFORE INSERT ON payment_events WHEN NEW.action='receive' AND EXISTS(SELECT 1 FROM specialty_order_links WHERE order_id=NEW.order_id) BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM specialty_trace_context WHERE order_id=NEW.order_id AND can_execute=1) THEN RAISE(ABORT,'specialty current approval required') END; END;

CREATE TRIGGER payment_events_specialty_capture AFTER INSERT ON payment_events WHEN NEW.action='receive' BEGIN INSERT INTO specialty_execution_refs SELECT NEW.id,'payment',c.id,c.approval_id,c.trace_sequence,c.specialty_sequence,c.parameter_sequence,coalesce((SELECT max(revision) FROM processing_events WHERE job_id=NULL),0),coalesce((SELECT basis_json FROM specialty_lot_basis WHERE job_id=NULL),'[]'),NEW.created_at FROM specialty_trace_context c WHERE c.order_id=NEW.order_id; END;

CREATE TRIGGER inventory_order_events_specialty_gate BEFORE INSERT ON inventory_order_events WHEN NEW.action='reserve' AND EXISTS(SELECT 1 FROM specialty_order_links WHERE order_id=NEW.order_id) BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM specialty_trace_context WHERE order_id=NEW.order_id AND can_execute=1) THEN RAISE(ABORT,'specialty current approval required') END; END;

CREATE TRIGGER inventory_order_events_specialty_capture AFTER INSERT ON inventory_order_events WHEN NEW.action='reserve' BEGIN INSERT INTO specialty_execution_refs SELECT NEW.id,'reservation',c.id,c.approval_id,c.trace_sequence,c.specialty_sequence,c.parameter_sequence,coalesce((SELECT max(revision) FROM processing_events WHERE job_id=NULL),0),coalesce((SELECT basis_json FROM specialty_lot_basis WHERE job_id=NULL),'[]'),NEW.created_at FROM specialty_trace_context c WHERE c.order_id=NEW.order_id; END;

CREATE TRIGGER inventory_outbounds_specialty_gate BEFORE INSERT ON inventory_outbounds WHEN 1 AND EXISTS(SELECT 1 FROM specialty_order_links WHERE order_id=NEW.order_id) BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM specialty_trace_context WHERE order_id=NEW.order_id AND can_execute=1) THEN RAISE(ABORT,'specialty current approval required') END; SELECT CASE WHEN EXISTS(SELECT 1 FROM specialty_lot_coverage WHERE job_id=(SELECT job_id FROM fulfillment_events WHERE id=NEW.delivery_id) AND position=NEW.position AND traced_quantity<received_quantity) THEN RAISE(ABORT,'specialty lot trace incomplete') END; END;

CREATE TRIGGER inventory_outbounds_specialty_capture AFTER INSERT ON inventory_outbounds WHEN 1 BEGIN INSERT INTO specialty_execution_refs SELECT NEW.id,'outbound',c.id,c.approval_id,c.trace_sequence,c.specialty_sequence,c.parameter_sequence,coalesce((SELECT max(revision) FROM processing_events WHERE job_id=(SELECT job_id FROM fulfillment_events WHERE id=NEW.delivery_id)),0),coalesce((SELECT basis_json FROM specialty_lot_basis WHERE job_id=(SELECT job_id FROM fulfillment_events WHERE id=NEW.delivery_id)),'[]'),NEW.created_at FROM specialty_trace_context c WHERE c.order_id=NEW.order_id; END;

CREATE TRIGGER specialty_execution_ref_ready BEFORE INSERT ON specialty_execution_refs WHEN NOT EXISTS(SELECT 1 FROM specialty_trace_context c WHERE c.id=NEW.link_id AND c.approval_id=NEW.approval_id AND c.can_execute=1 AND c.trace_sequence=NEW.trace_sequence AND c.specialty_sequence=NEW.specialty_sequence AND c.parameter_sequence=NEW.parameter_sequence) BEGIN SELECT RAISE(ABORT,'specialty execution snapshot mismatch'); END;

CREATE TRIGGER specialty_execution_actual_ready BEFORE INSERT ON specialty_execution_refs WHEN NOT(NEW.kind='processing_job' AND EXISTS(SELECT 1 FROM processing_jobs n WHERE n.id=NEW.event_id AND n.created_at=NEW.created_at AND (1) AND n.order_id=(SELECT order_id FROM specialty_order_links WHERE id=NEW.link_id) AND NEW.processing_revision=coalesce((SELECT max(revision) FROM processing_events WHERE job_id=NULL),0) AND NEW.lot_basis_json=coalesce((SELECT basis_json FROM specialty_lot_basis WHERE job_id=NULL),'[]')) OR NEW.kind='processing' AND EXISTS(SELECT 1 FROM processing_events n WHERE n.id=NEW.event_id AND n.created_at=NEW.created_at AND (n.action IN('plan','start','complete')) AND (SELECT order_id FROM processing_jobs WHERE id=n.job_id)=(SELECT order_id FROM specialty_order_links WHERE id=NEW.link_id) AND NEW.processing_revision=coalesce((SELECT max(revision) FROM processing_events WHERE job_id=n.job_id),0) AND NEW.lot_basis_json=coalesce((SELECT basis_json FROM specialty_lot_basis WHERE job_id=n.job_id),'[]')) OR NEW.kind='fulfillment' AND EXISTS(SELECT 1 FROM fulfillment_events n WHERE n.id=NEW.event_id AND n.created_at=NEW.created_at AND (n.action<>'check_fail') AND (SELECT order_id FROM processing_jobs WHERE id=n.job_id)=(SELECT order_id FROM specialty_order_links WHERE id=NEW.link_id) AND NEW.processing_revision=coalesce((SELECT max(revision) FROM processing_events WHERE job_id=n.job_id),0) AND NEW.lot_basis_json=coalesce((SELECT basis_json FROM specialty_lot_basis WHERE job_id=n.job_id),'[]')) OR NEW.kind='payment' AND EXISTS(SELECT 1 FROM payment_events n WHERE n.id=NEW.event_id AND n.created_at=NEW.created_at AND (n.action='receive') AND n.order_id=(SELECT order_id FROM specialty_order_links WHERE id=NEW.link_id) AND NEW.processing_revision=coalesce((SELECT max(revision) FROM processing_events WHERE job_id=NULL),0) AND NEW.lot_basis_json=coalesce((SELECT basis_json FROM specialty_lot_basis WHERE job_id=NULL),'[]')) OR NEW.kind='reservation' AND EXISTS(SELECT 1 FROM inventory_order_events n WHERE n.id=NEW.event_id AND n.created_at=NEW.created_at AND (n.action='reserve') AND n.order_id=(SELECT order_id FROM specialty_order_links WHERE id=NEW.link_id) AND NEW.processing_revision=coalesce((SELECT max(revision) FROM processing_events WHERE job_id=NULL),0) AND NEW.lot_basis_json=coalesce((SELECT basis_json FROM specialty_lot_basis WHERE job_id=NULL),'[]')) OR NEW.kind='outbound' AND EXISTS(SELECT 1 FROM inventory_outbounds n WHERE n.id=NEW.event_id AND n.created_at=NEW.created_at AND (1) AND n.order_id=(SELECT order_id FROM specialty_order_links WHERE id=NEW.link_id) AND NEW.processing_revision=coalesce((SELECT max(revision) FROM processing_events WHERE job_id=(SELECT job_id FROM fulfillment_events WHERE id=n.delivery_id)),0) AND NEW.lot_basis_json=coalesce((SELECT basis_json FROM specialty_lot_basis WHERE job_id=(SELECT job_id FROM fulfillment_events WHERE id=n.delivery_id)),'[]'))) BEGIN SELECT RAISE(ABORT,'specialty actual execution mismatch'); END;
